import {folderLayers} from './folders.js';
import {occupiedBounds} from './layer-compositor.js';
export const clipBudget=8*1024*1024;
export function sourceLayers(b,id){const l=b.layers.find(l=>l.id===id);return l?[l]:(b.folders||[]).some(f=>f.id===id)?folderLayers(b,id):[];}
export function validateClipping(b){for(const l of b.layers){if(Object.hasOwn(l,'alphaLock')&&(b.version!==7||typeof l.alphaLock!=='boolean'))throw Error('Invalid alpha lock');if(Object.hasOwn(l,'clipSource')){if(b.version!==7||!(l.clipSource===null||typeof l.clipSource==='string'&&l.clipSource))throw Error('Invalid clipping source');if(l.clipSource!==null){const sources=sourceLayers(b,l.clipSource);if(!sources.length||sources.some(s=>b.layers.indexOf(s)>=b.layers.indexOf(l)))throw Error('Clipping source must be a nonempty layer or folder below this layer');}}}}
export function mutateClipping(b,l,action,value){b.version=7;b.folders=b.folders||[];if(action==='alphaLock')l.alphaLock=value;else if(action==='clipSource')l.clipSource=value;else throw Error('Unknown clipping action');}
export function createClipCache({budgetBytes=clipBudget,makeCanvas=()=>document.createElement('canvas')}={}){
 let board=null,key='',needed=new Set(),sources=new Map(),groups=new Map(),residentBytes=0,captures=0,hits=0,serial=0;
 const free=e=>{if(e?.canvas){residentBytes-=e.bytes;e.canvas.width=0;e.canvas.height=0;}};
 function clear(){for(const e of [...sources.values(),...groups.values()])free(e);sources.clear();groups.clear();board=null;key='';needed.clear();}
 function prepare(b){if(board!==b){clear();board=b;needed=new Set(b.layers.flatMap(l=>l.clipSource?sourceLayers(b,l.clipSource).map(s=>s.id):[]));}}
 function geometry(v,g){const next=[v.x,v.y,v.scale,g.w,g.h,g.d].join(',');if(next!==key){for(const e of [...sources.values(),...groups.values()])free(e);sources.clear();groups.clear();key=next;}}
 function allocate(bounds){if(!bounds)return {canvas:null,bytes:0,token:++serial};const bytes=bounds.width*bounds.height*4;if(residentBytes+Math.max(bytes,300*150*4)>budgetBytes)throw Error('Clipping cache limit · zoom out or reduce the visible source area');const canvas=makeCanvas();canvas.width=0;canvas.height=0;canvas.width=bounds.width;canvas.height=bounds.height;residentBytes+=bytes;return {canvas,bytes,...bounds,token:++serial};}
 function capture(l,canvas,v,g,liveToken){if(!needed.has(l.id))return;geometry(v,g);const old=sources.get(l.id);if(old&&old.layer===l&&old.liveToken===liveToken){hits++;return;}for(const e of groups.values())free(e);groups.clear();free(old);sources.delete(l.id);const data=canvas.getContext('2d').getImageData(0,0,g.w,g.h).data,entry=allocate(occupiedBounds(data,g.w,g.h));entry.layer=l;entry.liveToken=liveToken;if(entry.canvas){const c=entry.canvas.getContext('2d');c.globalAlpha=l.opacity;c.drawImage(canvas,entry.x,entry.y,entry.width,entry.height,0,0,entry.width,entry.height);}sources.set(l.id,entry);captures++;}
 function matte(id){const leaves=sourceLayers(board,id).filter(l=>l.visible&&l.opacity>0),entries=leaves.map(l=>sources.get(l.id));if(entries.some(e=>!e))throw Error('Clipping source cache missing');if(leaves.length===1)return entries[0];const token=entries.map(e=>e.token).join(','),old=groups.get(id);if(old?.sourceToken===token)return old;free(old);groups.delete(id);const filled=entries.filter(e=>e.canvas);let bounds=null;if(filled.length){const x=Math.min(...filled.map(e=>e.x)),y=Math.min(...filled.map(e=>e.y));bounds={x,y,width:Math.max(...filled.map(e=>e.x+e.width))-x,height:Math.max(...filled.map(e=>e.y+e.height))-y};}const entry=allocate(bounds);entry.sourceToken=token;if(entry.canvas){const c=entry.canvas.getContext('2d');for(const e of filled)c.drawImage(e.canvas,e.x-entry.x,e.y-entry.y);}groups.set(id,entry);return entry;}
 function apply(l,canvas){if(!l.clipSource)return;const entry=matte(l.clipSource),ctx=canvas.getContext('2d');ctx.save();try{ctx.setTransform(1,0,0,1,0,0);ctx.globalAlpha=1;if(!entry?.canvas)ctx.clearRect(0,0,canvas.width,canvas.height);else{ctx.globalCompositeOperation='destination-in';ctx.drawImage(entry.canvas,entry.x,entry.y);}}finally{ctx.restore();}}
 return {prepare,capture,apply,clear,diagnostics:()=>Object.freeze({budgetBytes,residentBytes,captures,hits,sources:sources.size,groups:groups.size})};
}
